SELECT count(*) num, from_unixtime(round(product_add_time / 1000), '%m-%d') AS time FROM pt_product_index
AND product_add_time BETWEEN #{startTime} AND #{endTime}
AND store_id = #{storeId}
GROUP BY time ORDER BY product_add_time

